              "\u041E\u0431\u044B\u0447\u043D\u043E \u0443 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u043F\u044F\u0442\u044C \u043A\u043E\u0441\u0442\u0435\u0439. \u0421\u0432\u043E\u0439 \u0431\u0440\u043E\u0441\u043E\u043A \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0435\u0448\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 V. \u0421\u0442\u0430\u0432\u043A\u0430 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u043A\u043E\u0441\u0442\u0438 \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u00AB\u0442\u0440\u0438 \u0447\u0435\u0442\u0432\u0451\u0440\u043A\u0438\u00BB \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043E \u043D\u0430 \u0441\u0442\u043E\u043B\u0435 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 \u0442\u0440\u0451\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0441\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C \u0447\u0435\u0442\u044B\u0440\u0435.",
              "\u041D\u0430\u0436\u043C\u0438 B, \u0447\u0442\u043E\u0431\u044B \u0443\u043A\u0430\u0437\u0430\u0442\u044C \u0447\u0438\u0441\u043B\u043E \u043A\u043E\u0441\u0442\u0435\u0439 \u0438 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435. \u041C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443 \u043D\u0430 \u043D\u0443\u0436\u043D\u043E\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C Enter. L \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u0441\u0442\u0430\u0432\u043A\u0443. \u0414\u043B\u044F \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u044F \u043D\u0430\u0437\u043E\u0432\u0438 \u0431\u043E\u043B\u044C\u0448\u0435 \u043A\u043E\u0441\u0442\u0435\u0439 \u0438\u043B\u0438 \u0442\u043E \u0436\u0435 \u0447\u0438\u0441\u043B\u043E \u0441 \u0431\u043E\u043B\u0435\u0435 \u0432\u044B\u0441\u043E\u043A\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C.",
              "\u0415\u0441\u043B\u0438 \u0441\u043E\u043C\u043D\u0435\u0432\u0430\u0435\u0448\u044C\u0441\u044F \u0432 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0441\u0442\u0430\u0432\u043A\u0435, \u043D\u0430\u0436\u043C\u0438 K. \u0418\u0433\u0440\u043E\u043A\u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u043A\u043E\u0441\u0442\u0438. \u0415\u0441\u043B\u0438 \u043D\u0443\u0436\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043C\u0435\u043D\u044C\u0448\u0435, \u0447\u0435\u043C \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043E, \u0442\u0435\u0440\u044F\u0435\u0442 \u043A\u043E\u0441\u0442\u044C \u0442\u043E\u0442, \u043A\u0442\u043E \u0441\u0434\u0435\u043B\u0430\u043B \u0441\u0442\u0430\u0432\u043A\u0443. \u0415\u0441\u043B\u0438 \u0438\u0445 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0436\u0435 \u0438\u043B\u0438 \u0431\u043E\u043B\u044C\u0448\u0435, \u043A\u043E\u0441\u0442\u044C \u0442\u0435\u0440\u044F\u0435\u0448\u044C \u0442\u044B.",
              "\u0412 \u043E\u0431\u044B\u0447\u043D\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 D \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043E \u0447\u0438\u0441\u043B\u043E \u043A\u043E\u0441\u0442\u0435\u0439 \u043D\u0430\u0437\u0432\u0430\u043D\u043E \u0442\u043E\u0447\u043D\u043E. \u0415\u0441\u043B\u0438 \u0442\u044B \u043F\u0440\u0430\u0432, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0442\u0435\u0440\u044F\u044E\u0442 \u043F\u043E \u043A\u043E\u0441\u0442\u0438, \u0430 \u0442\u044B \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0448\u044C \u043D\u043E\u0432\u044B\u0439 \u0440\u0430\u0443\u043D\u0434. \u041F\u0440\u0438 \u043E\u0448\u0438\u0431\u043A\u0435 \u043A\u043E\u0441\u0442\u044C \u0442\u0435\u0440\u044F\u0435\u0448\u044C \u0442\u044B. \u041F\u043E\u0441\u043B\u0435 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u043F\u043E\u0442\u0435\u0440\u044F\u0432\u0448\u0438\u0439 \u043A\u043E\u0441\u0442\u044C \u0438\u043B\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A, \u0435\u0441\u043B\u0438 \u0442\u043E\u0442 \u0432\u044B\u0431\u044B\u043B. \u0411\u0435\u0437 \u043A\u043E\u0441\u0442\u0435\u0439 \u0438\u0433\u0440\u043E\u043A \u0432\u044B\u0431\u044B\u0432\u0430\u0435\u0442. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0438\u0433\u0440\u043E\u043A \u0441 \u043A\u043E\u0441\u0442\u044F\u043C\u0438."),
            rule_section(:variants, "\u041A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0438 \u041F\u0435\u0440\u0443\u0434\u043E",
              "\u0412 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u043D\u0435\u043B\u044C\u0437\u044F \u0437\u0430\u044F\u0432\u043B\u044F\u0442\u044C \u0442\u043E\u0447\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E; \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0435\u0434\u0438\u043D\u0438\u0446\u0430\u043C\u0438.",
              "\u0412 \u041F\u0435\u0440\u0443\u0434\u043E \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0442 \u0434\u0440\u0443\u0433\u0438\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F. \u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u0440\u0430\u0443\u043D\u0434 \u043D\u0435\u043B\u044C\u0437\u044F \u043D\u0430\u0447\u0438\u043D\u0430\u0442\u044C \u0441 \u0435\u0434\u0438\u043D\u0438\u0446. \u0427\u0442\u043E\u0431\u044B \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043D\u0430 \u043D\u0438\u0445, \u043D\u0430\u0437\u043E\u0432\u0438 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u044B \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0433\u043E \u0447\u0438\u0441\u043B\u0430 \u043A\u043E\u0441\u0442\u0435\u0439 \u0441 \u043E\u043A\u0440\u0443\u0433\u043B\u0435\u043D\u0438\u0435\u043C \u0432\u0432\u0435\u0440\u0445. \u0427\u0442\u043E\u0431\u044B \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u0434\u0440\u0443\u0433\u043E\u043C\u0443 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044E, \u043D\u0430\u0437\u043E\u0432\u0438 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 \u0443\u0434\u0432\u043E\u0435\u043D\u043D\u043E\u0433\u043E \u0447\u0438\u0441\u043B\u0430 \u0435\u0434\u0438\u043D\u0438\u0446 \u043F\u043B\u044E\u0441 \u043E\u0434\u0438\u043D. \u0415\u0441\u043B\u0438 \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0448\u044C \u0435\u0434\u0438\u043D\u0438\u0446\u044B, \u0443\u0432\u0435\u043B\u0438\u0447\u044C \u0438\u0445 \u0447\u0438\u0441\u043B\u043E."),
            rule_section(:special, "\u041F\u0430\u043B\u0438\u0444\u0438\u043A\u043E \u0438 \u041A\u0430\u043B\u044C\u0441\u0430",
              "\u0415\u0441\u043B\u0438 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u041F\u0430\u043B\u0438\u0444\u0438\u043A\u043E, \u043F\u0435\u0440\u0432\u0430\u044F \u043F\u043E\u0442\u0435\u0440\u044F \u043F\u0440\u0435\u0434\u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u043A\u043E\u0441\u0442\u0438 \u043C\u0435\u043D\u044F\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0440\u0430\u0443\u043D\u0434, \u0435\u0441\u043B\u0438 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 \u0442\u0440\u0451\u0445. \u0415\u0434\u0438\u043D\u0438\u0446\u044B \u043D\u0435 \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0442 \u0434\u0440\u0443\u0433\u0438\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F. \u041C\u0435\u043D\u044F\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0432 \u0441\u0442\u0430\u0432\u043A\u0435 \u043C\u043E\u0433\u0443\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0442\u0435, \u043A\u0442\u043E \u0443\u0436\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u043B \u0440\u0430\u0443\u043D\u0434 \u041F\u0430\u043B\u0438\u0444\u0438\u043A\u043E.",
              "\u0415\u0441\u043B\u0438 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u0430 \u041A\u0430\u043B\u044C\u0441\u0430, \u043A\u043B\u0430\u0432\u0438\u0448\u0430 D \u0437\u0430\u044F\u0432\u043B\u044F\u0435\u0442 \u0442\u043E\u0447\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u0434\u0430\u0436\u0435 \u0432\u043D\u0435 \u043E\u0447\u0435\u0440\u0435\u0434\u0438, \u043D\u043E \u043D\u0435 \u0434\u043B\u044F \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0439 \u0441\u0442\u0430\u0432\u043A\u0438. \u0417\u0430 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u043E\u0434\u043D\u0430 \u043A\u043E\u0441\u0442\u044C, \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0447\u0438\u0441\u043B\u0430. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0440\u0430\u0443\u043D\u0434 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0438\u0433\u0440\u043E\u043A, \u043F\u043E\u0442\u0435\u0440\u044F\u0432\u0448\u0438\u0439 \u043A\u043E\u0441\u0442\u044C. \u041E\u0448\u0438\u0431\u043A\u0430 \u0441\u0442\u043E\u0438\u0442 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438."),
            rule_section(:privacy, "\u0412\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u043A \u0441\u0442\u043E\u043B\u0443",
              "\u041F\u043E\u0441\u043B\u0435 \u0440\u0430\u0437\u0440\u044B\u0432\u0430 \u0441\u043E\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u044F \u0432\u0435\u0440\u043D\u0438\u0441\u044C \u0438\u0437 \u0442\u043E\u0433\u043E \u0436\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u044F ELTEN, \u0447\u0442\u043E\u0431\u044B \u0432\u0438\u0434\u0435\u0442\u044C \u0441\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438. \u041F\u043E\u043A\u0430 \u043A\u043E\u0441\u0442\u0438 \u0441\u043A\u0440\u044B\u0442\u044B, \u043D\u0435\u043B\u044C\u0437\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u043F\u0430\u0440\u0442\u0438\u044E \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u0442\u044C \u044D\u0442\u0438 \u043A\u043E\u0441\u0442\u0438 \u0434\u0440\u0443\u0433\u043E\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443."),
            rule_section(:controls, "\u0413\u043E\u0440\u044F\u0447\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438",
              "V: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438",
              "L: \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u0441\u0442\u0430\u0432\u043A\u0443",
              "B: \u0432\u0432\u0435\u0441\u0442\u0438 \u0441\u0442\u0430\u0432\u043A\u0443",
              "K: \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0441\u0442\u0430\u0432\u043A\u0443",
              "D: \u0437\u0430\u044F\u0432\u0438\u0442\u044C \u0442\u043E\u0447\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E, \u0435\u0441\u043B\u0438 \u044D\u0442\u043E \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E")
          ]
